import 'dart:io';
import 'package:yaml/yaml.dart';

void main() {
  final manifest = loadYaml(File('pubspec.yaml').readAsStringSync()) as YamlMap;
  final version = manifest['version'];
  if (version is! String ||
      !RegExp(r'^\d+\.\d+\.\d+\+\d+$').hasMatch(version)) {
    throw const FormatException('Expected a semantic version and build number');
  }
  File('lib/app/build_info.g.dart').writeAsStringSync(
      '// Generated by tool/generate_build_info.dart. Do not edit.\n'
      "const rainlinkVersion = '$version';\n");
}
